def is_console(stream) -> bool:
    try:
        return stream.isatty()
    except Exception:
        return False


def read_file_or_stdin(path: str) -> bytes:
    if path in ("-", "stdin"):
        return sys.stdin.buffer.read()
    with open(path, "rb") as handle:
        return handle.read()


def load_dictionary(cfg: Config) -> None:
    if not cfg.dictionary_path:
        return
    with open(cfg.dictionary_path, "rb") as handle:
        cfg.dictionary = handle.read()


def compression_level_for_cfg(cfg: Config) -> int:
    if cfg.fast_acceleration is not None:
        return -int(cfg.fast_acceleration)
    level = cfg.compression_level
    if level <= 1:
        return 0
    return level


def make_preferences(cfg: Config, input_size: int) -> LZ4Preferences:
    prefs = LZ4Preferences()
    prefs.frameInfo.blockSizeID = cfg.block_size_id
    prefs.frameInfo.blockMode = cfg.block_mode
    prefs.frameInfo.contentChecksumFlag = 1 if cfg.content_checksum else 0
    prefs.frameInfo.frameType = 0
    prefs.frameInfo.contentSize = input_size if cfg.content_size else 0
    prefs.frameInfo.dictID = 0
    prefs.frameInfo.blockChecksumFlag = 1 if cfg.block_checksum else 0
    prefs.compressionLevel = compression_level_for_cfg(cfg)
    prefs.autoFlush = 0
    prefs.favorDecSpeed = 1 if cfg.favor_dec_speed else 0
    return prefs


