def format_ratio(input_size: int, output_size: int) -> str:
    if input_size == 0:
        return "0.00%"
    return f"{(output_size * 100.0) / input_size:.2f}%"


def summarize_compression(input_size: int, output_size: int) -> str:
    return (
        f"\rRead : {input_size // (1024 * 1024)} MiB   ==> {format_ratio(input_size, output_size)}   "
        "\r                                                                                \r"
        f"Compressed {input_size} bytes into {output_size} bytes ==> {format_ratio(input_size, output_size)}"
    )


def summarize_decompression(path: str, output_size: int) -> str:
    return (
        f"\rDecompressed : {output_size // (1024 * 1024)} MiB  "
        "\r                                                                                \r"
        f"{path:<24} : decoded {output_size} bytes "
    )


def open_output(path: str):
    if path == "null":
        return None
    return open(path, "wb")


def ensure_can_write(path: str, cfg: Config, input_is_stream: bool) -> bool:
    if path in ("-", "stdout", "null"):
        if path in ("-", "stdout") and is_console(sys.stdout) and not cfg.stdout_mode:
            stderr_print("refusing to write to console without -c ", quiet_level=cfg.quiet, is_error=True)
            return False
        return True
    if cfg.force or not os.path.exists(path):
        return True
    prompt = f"{path} already exists; do you want to overwrite (y/N) ? "
    if not input_is_stream and sys.stdin.isatty():
        sys.stderr.write(prompt)
        sys.stderr.flush()
        answer = sys.stdin.readline()
    else:
        stderr_print(prompt, quiet_level=0, is_error=True, end="")
        answer = ""
    if not answer or answer[:1].lower() != "y":
        stderr_print("    not overwritten  ", quiet_level=0, is_error=True)
        return False
    return True


def output_kind(path: Optional[str], cfg: Config, input_path: str, mode: str) -> str:
    if cfg.test_mode:
        return "null"
    if path:
        if path in ("-", "stdout"):
            return "stdout"
        if path == "null":
            return "null"
        return path
    if cfg.stdout_mode:
        return "stdout"
    if input_path in ("-", "stdin"):
        return "stdout"
    if mode == "compress":
        return f"{input_path}.lz4"
    if input_path.endswith(".lz4"):
        return input_path[:-4]
    raise ParameterError("Cannot determine an output filename")


def auto_mode_for_input(cfg: Config, input_path: str) -> str:
    if cfg.mode in {"compress", "decompress"}:
        return cfg.mode
    if input_path not in ("-", "stdin") and input_path.endswith(".lz4"):
        return "decompress"
    return "compress"


def write_output_bytes(data: bytes, destination: str) -> None:
    if destination == "stdout":
        sys.stdout.buffer.write(data)
        sys.stdout.buffer.flush()
        return
    if destination == "null":
        return
    with open(destination, "wb") as handle:
        handle.write(data)


def process_one(input_path: str, requested_output: Optional[str], cfg: Config) -> int:
    mode = auto_mode_for_input(cfg, input_path)
    destination = output_kind(requested_output, cfg, input_path, mode)
    input_is_stream = input_path in ("-", "stdin")

    if input_is_stream and is_console(sys.stdin):
        stderr_print("refusing to read from a console", quiet_level=cfg.quiet, is_error=True)
        return 1
    if destination == "stdout" and is_console(sys.stdout) and not cfg.stdout_mode:
        stderr_print("refusing to write to console without -c ", quiet_level=cfg.quiet, is_error=True)
        return 1
    if not ensure_can_write(destination, cfg, input_is_stream):
        return 1

    try:
        payload = read_file_or_stdin(input_path)
    except FileNotFoundError:
        stderr_print(f"{input_path}: No such file or directory ", quiet_level=cfg.quiet, is_error=True)
        return 1

    if destination not in ("stdout", "null") and requested_output is None and not input_is_stream and not cfg.multiple and not cfg.quiet:
        if mode == "compress":
            stderr_print(f"Compressed filename will be : {destination} ", quiet_level=cfg.quiet)
        else:
            stderr_print(f"Decoding file {destination} ", quiet_level=cfg.quiet)

    try:
        if mode == "compress":
            if cfg.legacy:
                stderr_print("Legacy format support is not implemented ", quiet_level=cfg.quiet, is_error=True)
                return 1
            result = compress_bytes(payload, cfg)
            if not cfg.test_mode:
                write_output_bytes(result, destination)
            if not cfg.multiple and not cfg.quiet:
                stderr_print(summarize_compression(len(payload), len(result)), quiet_level=cfg.quiet)
        else:
            decompressed, _ = inspect_and_maybe_decompress(payload, cfg.dictionary, keep_output=not cfg.test_mode)
            if not cfg.test_mode:
                write_output_bytes(decompressed, destination)
            if not cfg.multiple and not cfg.quiet:
                stderr_print(summarize_decompression(input_path, len(decompressed)), quiet_level=cfg.quiet)
    except FileNotFoundError:
        stderr_print(f"{input_path}: No such file or directory ", quiet_level=cfg.quiet, is_error=True)
        return 1
    except LZ4Error as exc:
        stderr_print(f"Error {exc.code} : {exc.message} ", quiet_level=cfg.quiet, is_error=True)
        return exc.code

    if cfg.remove_source and not input_is_stream:
        try:
            os.unlink(input_path)
        except OSError:
            pass
    return 0


def list_files(paths: Sequence[str], cfg: Config) -> int:
    sys.stdout.write("    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename\n")
    exit_code = 0
    for path in paths:
        try:
            data = read_file_or_stdin(path)
        except FileNotFoundError:
            stderr_print(f"{path}: No such file or directory ", quiet_level=cfg.quiet, is_error=True)
            exit_code = 1
            continue
        try:
            _, summary = inspect_and_maybe_decompress(data, cfg.dictionary, keep_output=False)
        except LZ4Error as exc:
            stderr_print(f"Error {exc.code} : {exc.message} ", quiet_level=cfg.quiet, is_error=True)
            exit_code = exc.code
            continue
        compressed = len(data)
        if compressed >= 1024:
            compressed_text = f"{compressed / 1024.0:10.2f}K"
        else:
            compressed_text = f"{compressed:12.2f}"
        if summary.content_size is None:
            uncompressed_text = "            -"
            ratio_text = "       -"
        else:
            uncompressed_text = f"{summary.content_size:12.2f}"
            ratio_text = f"{(compressed * 100.0) / summary.content_size:9.2f}%"
        block_mode = "I" if summary.block_mode == LZ4F_BLOCK_INDEPENDENT else "D"
        basename = os.path.basename(path)
        sys.stdout.write(
            f"{summary.frames:10d}       LZ4Frame   B{summary.block_size_id}{block_mode}"
            f"{compressed_text}{uncompressed_text}{ratio_text}  {basename} \n"
        )
    return exit_code


def collect_inputs(positionals: Sequence[str], recursive: bool) -> List[str]:
    result: List[str] = []
    for item in positionals:
        if item in ("-", "stdin"):
            result.append(item)
            continue
        try:
            st = os.stat(item)
        except FileNotFoundError:
            result.append(item)
            continue
        if stat.S_ISDIR(st.st_mode):
            if not recursive:
                result.append(item)
                continue
            for root, _, files in os.walk(item):
                for name in sorted(files):
                    result.append(os.path.join(root, name))
        else:
            result.append(item)
    return result


def run_benchmark(paths: Sequence[str], cfg: Config) -> int:
    levels = range(cfg.bench_start, cfg.bench_end + 1)
    for level in levels:
        bench_cfg = Config(**{**cfg.__dict__})
        bench_cfg.compression_level = level
        bench_cfg.fast_acceleration = None
        for path in paths:
            try:
                data = read_file_or_stdin(path)
            except FileNotFoundError:
                stderr_print(f"{path}: No such file or directory ", quiet_level=cfg.quiet, is_error=True)
                return 1
            start = time.perf_counter()
            loops = 0
            compressed = b""
            while time.perf_counter() - start < max(0.01, cfg.bench_seconds):
                compressed = compress_bytes(data, bench_cfg)
                inspect_and_maybe_decompress(compressed, None, keep_output=False)
                loops += 1
            elapsed = max(time.perf_counter() - start, 0.000001)
            comp_speed = ((len(data) * loops) / elapsed) / (1024 * 1024)
            decomp_speed = (((len(data) + len(compressed)) * loops) / elapsed) / (1024 * 1024)
            ratio = (len(data) / max(len(compressed), 1)) if compressed else 0.0
            sys.stdout.write(
                f" {level}#{os.path.basename(path):>18} : {len(data):9d} -> {len(compressed):9d}"
                f" ({ratio:0.3f}), {comp_speed:5.1f} MB/s, {decomp_speed:5.1f} MB/s\n"
            )
    return 0


